	}).finally(() => owner.children.delete(joined));
	owner.children.add(joined);
}

/** Used only for concrete unaudited subfeatures, never as a substitute for retention. */
export function markAppStreamProducerUnknown(stream: object, reason: string): void {
	const owner = appStreamProducers.get(stream);
	if (!owner || owner.closed) throw new Error("Stream producer ownership is unavailable");
	owner.unknown.add(reason);
}

