const appHostContext = new AsyncLocalStorage<{ owner: AppSdkHostOwner; token: object }>();
/** Session-local physical ownership, independent of bounded/logical SDK shutdown. */
export class AppSdkHostOwner {
	readonly #epoch = crypto.randomUUID();
	#revision = 0;
	readonly #tasks = new Set<Promise<void>>();
	readonly #active = new Set<object>();
	readonly #timers = new Map<ReturnType<typeof setTimeout>, () => void>();
	readonly #unknown = new Set<string>();
	markUnknown(reason: string): void { if (!this.#unknown.has(reason)) { this.#unknown.add(reason); this.#revision++; } }
	getAppLifecycleActivity() {
		return { generation: `${this.#epoch}:${this.#revision}`, complete: this.#unknown.size === 0,
			starting: 0, queued: this.#timers.size, running: this.#tasks.size, settling: 0, unknown: [...this.#unknown] };
	}
	own<T>(operation: () => T | PromiseLike<T>): Promise<T> {
		const reservation = Promise.withResolvers<void>(); const token = {};
		this.#tasks.add(reservation.promise); this.#active.add(token); this.#revision++;
		const finish = () => { this.#tasks.delete(reservation.promise); this.#active.delete(token); this.#revision++; reservation.resolve(); };
		try { return Promise.resolve(appHostContext.run({ owner: this, token }, operation)).finally(finish); }
		catch (error) { finish(); return Promise.reject(error); }
	}
	retain<T>(task: PromiseLike<T>): Promise<T> { return this.own(() => task); }
	schedule(operation: () => void | Promise<void>, delay: number): ReturnType<typeof setTimeout> {
		const due = Promise.withResolvers<void>();
		void this.own(() => due.promise);
		const timer = setTimeout(() => {
			this.#timers.delete(timer); this.#revision++;
			void this.own(async () => {
				try { await operation(); }
				catch { this.markUnknown("sdk_host_callback_failed"); }
				finally { due.resolve(); }
			});
		}, delay);
		this.#timers.set(timer, due.resolve); this.#revision++;
		return timer;
	}
	cancelTimer(timer: ReturnType<typeof setTimeout>): void {
		clearTimeout(timer); const release = this.#timers.get(timer);
		if (release) { this.#timers.delete(timer); this.#revision++; release(); }
	}
	async awaitAppLifecycleSettlement(): Promise<void> {
		const context = appHostContext.getStore();
		if (context?.owner === this && this.#active.has(context.token)) {
			this.markUnknown("sdk_host_reentrant_settlement");
			throw new Error("Cannot join SDK host ownership from its own callback");
		}
		while (this.#tasks.size) await Promise.allSettled([...this.#tasks]);
	}
}

